import * as adapter from './falco.json';

/**
 * Falco API v1 (docs.falco-app.be, OpenAPI on each reference page): production host
 * https://api.falco-app.be/v1, two headers on every call (X-Falco-App-Secret of the developer
 * application, X-Falco-Api-Key generated by the Falco customer for that application).
 * Live part: FALCO_APP_SECRET=... FALCO_API_KEY=... RUN_FALCO_LIVE=1 npx jest src/adapters/be/falco
 * (reads only: organization, purchase documents, Peppol inbound documents).
 */

type Tool = {
  name: string;
  description: string;
  enabled?: boolean;
  parameters?: { properties?: Record<string, unknown>; required?: string[] };
  endpointMapping: { method: string; path: string; queryParams?: Record<string, unknown>; bodyMapping?: unknown; headers?: Record<string, unknown> };
  annotations?: { readOnlyHint?: boolean; destructiveHint?: boolean };
  responseMapping?: unknown;
};
const a = adapter as unknown as {
  slug: string;
  region: string;
  category: string;
  icon: string;
  requiredEnvVars: string[];
  envVarMeta?: Record<string, { pattern?: string; secret?: boolean; kind?: string }>;
  probe?: { tool: string; params?: Record<string, unknown> };
  instructions: string;
  connector: { type: string; baseUrl: string; authType: string; authConfig?: Record<string, any>; headers?: Record<string, string>; config?: Record<string, any> };
  tools: Tool[];
};
const tool = (name: string) => {
  const t = a.tools.find((x) => x.name === name);
  if (!t) throw new Error(`missing tool ${name}`);
  return t;
};
// Every argument a tool reads: {path} segments, "$arg" values and "${arg}" inside strings.
const used = (t: Tool) => {
  const m = t.endpointMapping;
  const out = new Set<string>();
  for (const [, p] of m.path.replace(/\{\{\w+\}\}/g, '').matchAll(/\{(\w+)\}/g)) out.add(p);
  const walk = (v: unknown) => {
    if (typeof v === 'string') {
      if (v.startsWith('$') && !v.includes('${')) out.add(v.slice(1));
      for (const [, p] of v.matchAll(/\$\{(\w+)\}/g)) out.add(p);
    } else if (v && typeof v === 'object') Object.values(v as Record<string, unknown>).forEach(walk);
  };
  walk(m.queryParams ?? {});
  walk(m.bodyMapping ?? {});
  walk(m.headers ?? {});
  return out;
};
const PREFIX = 'falco_';
const WRITES: string[] = ["falco_set_purchase_payment_status", "falco_send_invoice_response"];
const SWITCHED_OFF: string[] = ["falco_send_invoice_response", "falco_set_purchase_payment_status"];

describe('falco adapter: static spec conformance', () => {

  it('sends the application secret and the API key as the two documented headers to the production v1 host', () => {
    expect(a.requiredEnvVars).toEqual(['FALCO_APP_SECRET', 'FALCO_API_KEY']);
    expect(a.connector.baseUrl).toBe('https://api.falco-app.be/v1');
    expect(a.connector.authType).toBe('API_KEY');
    expect(a.connector.authConfig).toEqual({ headerName: 'X-Falco-Api-Key', apiKey: '{{FALCO_API_KEY}}', extraHeaders: { 'X-Falco-App-Secret': '{{FALCO_APP_SECRET}}' } });
    expect(a.envVarMeta?.FALCO_APP_SECRET.secret).toBe(true);
    expect(a.envVarMeta?.FALCO_API_KEY.secret).toBe(true);
    expect(new RegExp(a.envVarMeta?.FALCO_API_KEY.pattern ?? '').test('sk_live_abc123')).toBe(true);
    expect(new RegExp(a.envVarMeta?.FALCO_API_KEY.pattern ?? '').test('sk_test_abc123')).toBe(false);
    expect(a.probe?.tool).toBe('falco_get_organization');
    expect(tool('falco_get_organization').endpointMapping).toEqual({ method: 'GET', path: '/organization/whoami' });
  });

  it('maps the purchase, sale and Peppol inbound routes with their documented filters', () => {
    expect(tool('falco_list_purchase_documents').endpointMapping).toEqual({
      method: 'GET',
      path: '/documents/purchases',
      queryParams: { page: '$page', page_size: '$page_size', created_after: '$created_after', created_before: '$created_before', date_from: '$date_from', date_to: '$date_to', supplier_name: '$supplier_name', sort_by: '$sort_by', sort_direction: '$sort_direction' },
    });
    expect(tool('falco_get_purchase_document').endpointMapping.path).toBe('/documents/purchases/{document_id}');
    expect(tool('falco_download_purchase_document_file').endpointMapping.path).toBe('/documents/purchases/{document_id}/download/{file_identifier}');
    expect(tool('falco_list_sale_documents').endpointMapping).toMatchObject({ path: '/documents/sales', queryParams: { customer_name: '$customer_name', date_from: '$date_from' } });
    expect(tool('falco_get_sale_document').endpointMapping.path).toBe('/documents/sales/{document_id}');
    expect(tool('falco_list_peppol_inbound').endpointMapping).toEqual({
      method: 'GET',
      path: '/peppol/inbound',
      queryParams: { page: '$page', page_size: '$page_size', received_after: '$received_after', received_before: '$received_before', date_from: '$date_from', date_to: '$date_to', sender_vat_number: '$sender_vat_number', sender_name: '$sender_name', number: '$number', sort_by: '$sort_by', sort_direction: '$sort_direction' },
    });
    expect(tool('falco_get_peppol_inbound_document').endpointMapping.path).toBe('/peppol/inbound/{document_id}');
    expect(tool('falco_download_peppol_inbound_document').endpointMapping.path).toBe('/peppol/inbound/{document_id}/download');
    expect(tool('falco_find_peppol_participant').endpointMapping).toMatchObject({ path: '/peppol/participants/find', queryParams: { vat_number: '$vat_number' } });
    expect(tool('falco_check_peppol_participant').endpointMapping).toMatchObject({ path: '/peppol/participants/check', queryParams: { participant_identifier: '$participant_identifier' } });
    const ps = tool('falco_list_peppol_inbound').parameters?.properties?.page_size as { minimum: number; maximum: number };
    expect([ps.minimum, ps.maximum]).toEqual([20, 200]);
  });

  it('maps the invoicing module routes', () => {
    expect(tool('falco_list_customers').endpointMapping).toMatchObject({ path: '/customers', queryParams: { q: '$q', vat: '$vat', email: '$email' } });
    expect(tool('falco_get_customer').endpointMapping.path).toBe('/customers/{customer_id}');
    expect(tool('falco_list_articles').endpointMapping).toMatchObject({ path: '/articles', queryParams: { q: '$q' } });
    expect(tool('falco_list_invoices').endpointMapping).toMatchObject({ path: '/invoices', queryParams: { document_type: '$document_type', status: '$status', customer_id: '$customer_id' } });
    expect((tool('falco_list_invoices').parameters?.properties?.page_size as { maximum: number }).maximum).toBe(100);
    expect(tool('falco_get_invoice').endpointMapping.path).toBe('/invoices/{invoice_id}');
    expect(tool('falco_download_invoice_pdf').endpointMapping.path).toBe('/invoices/{invoice_id}/pdf');
  });

  it('sets a purchase payment status and sends Peppol responses only when switched on', () => {
    expect(tool('falco_set_purchase_payment_status').endpointMapping).toEqual({ method: 'PUT', path: '/documents/purchases/{document_id}/payment-status', bodyMapping: { payment_status: '$payment_status' } });
    expect(tool('falco_set_purchase_payment_status').annotations).toMatchObject({ readOnlyHint: false, destructiveHint: true });
    expect(tool('falco_send_invoice_response').endpointMapping).toEqual({ method: 'POST', path: '/peppol/inbound/{document_id}/response', bodyMapping: { response_code: '$response_code', status: '$status' } });
    expect(tool('falco_send_invoice_response').enabled).toBe(false);
    expect(tool('falco_set_purchase_payment_status').enabled).toBe(false);
  });

  it('every tool is prefixed, every declared parameter reaches the request and path parameters are required', () => {
    for (const t of a.tools) {
      expect(t.name.startsWith(PREFIX)).toBe(true);
      if (t.endpointMapping.method === 'static') continue;
      const u = used(t);
      const props = Object.keys(t.parameters?.properties ?? {});
      for (const p of props) expect(`${t.name}:${p}:${u.has(p)}`).toBe(`${t.name}:${p}:true`);
      for (const p of u) expect(`${t.name}:${p}:${props.includes(p)}`).toBe(`${t.name}:${p}:true`);
      for (const [, p] of t.endpointMapping.path.replace(/\{\{\w+\}\}/g, '').matchAll(/\{(\w+)\}/g)) expect(t.parameters?.required).toContain(p);
    }
  });

  it('writes are annotated, the risky ones installed switched off; reads are GET or marked read-only', () => {
    const off = a.tools.filter((t) => t.enabled === false).map((t) => t.name).sort();
    expect(off).toEqual([...SWITCHED_OFF].sort());
    for (const n of WRITES) expect(`${n}:${tool(n).annotations?.readOnlyHint}`).toBe(`${n}:false`);
    for (const t of a.tools) {
      if (WRITES.includes(t.name)) continue;
      expect(`${t.name}:${t.enabled}`).toBe(`${t.name}:undefined`);
      if (!['GET', 'static'].includes(t.endpointMapping.method) && !t.endpointMapping.method.startsWith('odata_')) expect(`${t.name}:${t.annotations?.readOnlyHint}`).toBe(`${t.name}:true`);
    }
  });

  it('documents every tool in the instructions, marks secrets and has no em dash', () => {
    for (const t of a.tools) expect(`${t.name}:${a.instructions.includes(t.name)}`).toBe(`${t.name}:true`);
    for (const [name, meta] of Object.entries(a.envVarMeta ?? {})) if (/PASSWORD|SECRET|TOKEN/.test(name) || name.endsWith('_KEY')) expect(`${name}:${meta.secret}`).toBe(`${name}:true`);
    expect(JSON.stringify(a)).not.toMatch(/\u2014/);
    if (a.probe) {
      const probe = tool(a.probe.tool);
      expect(probe.annotations?.readOnlyHint === false).toBe(false);
      expect(probe.parameters?.required ?? []).toEqual([]);
    }
  });
});

const live = process.env.RUN_FALCO_LIVE === '1' && process.env.FALCO_APP_SECRET && process.env.FALCO_API_KEY ? describe : describe.skip;
live('falco adapter: live (read-only)', () => {
  const headers = { 'X-Falco-App-Secret': process.env.FALCO_APP_SECRET as string, 'X-Falco-Api-Key': process.env.FALCO_API_KEY as string };
  it('reads the organization, purchase documents and Peppol inbound documents', async () => {
    const org = (await (await fetch(`${a.connector.baseUrl}/organization/whoami`, { headers })).json()) as { id: string; name: string };
    expect(typeof org.name).toBe('string');
    const purchases = (await (await fetch(`${a.connector.baseUrl}/documents/purchases?page=0&page_size=20`, { headers })).json()) as { data: unknown[] };
    expect(Array.isArray(purchases.data)).toBe(true);
    const inbound = (await (await fetch(`${a.connector.baseUrl}/peppol/inbound?page=0&page_size=20`, { headers })).json()) as { data: unknown[] };
    expect(Array.isArray(inbound.data)).toBe(true);
  }, 60_000);
});
